//! Configuration management CLI commands.//!//! Commands for viewing and modifying settings.//! Settings are stored in the database (env > DB > default).use std::sync::Arc;use clap::Subcommand;use crate::settings::Settings;#[derive(Subcommand, Debug, Clone)]pub enum ConfigCommand {    /// Generate a default config.toml file    Init {        /// Output path (default: ~/.ironclaw/config.toml)        #[arg(short, long)]        output: Option<std::path::PathBuf>,        /// Overwrite existing file        #[arg(long)]        force: bool,    },    /// List all settings and their current values    List {        /// Show only settings matching this prefix (e.g., "agent", "heartbeat")        #[arg(short, long)]        filter: Option<String>,    },    /// Get a specific setting value    Get {        /// Setting path (e.g., "agent.max_parallel_jobs")        path: String,    },    /// Set a setting value    Set {        /// Setting path (e.g., "agent.max_parallel_jobs")        path: String,        /// Value to set        value: String,    },    /// Reset a setting to its default value    Reset {        /// Setting path (e.g., "agent.max_parallel_jobs")        path: String,    },    /// Show the settings storage info    Path,}/// Run a config command.////// Connects to the database to read/write settings. Falls back to disk/// if the database is not available.pub async fn run_config_command(cmd: ConfigCommand) -> anyhow::Result<()> {    // Try to connect to the DB for settings access    let db: Option<Arc<dyn crate::db::Database>> = match connect_db().await {        Ok(d) => Some(d),        Err(e) => {            eprintln!(                "Warning: Could not connect to database ({}), using disk fallback",                e            );            None        }    };    let db_ref = db.as_deref();    match cmd {        ConfigCommand::Init { output, force } => init_toml(db_ref, output, force).await,        ConfigCommand::List { filter } => list_settings(db_ref, filter).await,        ConfigCommand::Get { path } => get_setting(db_ref, &path).await,        ConfigCommand::Set { path, value } => set_setting(db_ref, &path, &value).await,        ConfigCommand::Reset { path } => reset_setting(db_ref, &path).await,        ConfigCommand::Path => show_path(db_ref.is_some()),    }}/// Bootstrap a DB connection for config commands (backend-agnostic).async fn connect_db() -> anyhow::Result<Arc<dyn crate::db::Database>> {    let config = crate::config::Config::from_env()        .await        .map_err(|e| anyhow::anyhow!("{}", e))?;    crate::db::connect_from_config(&config.database)        .await        .map_err(|e| anyhow::anyhow!("{}", e))}const DEFAULT_USER_ID: &str = "default";/// Load settings: DB if available, else disk.async fn load_settings(store: Option<&dyn crate::db::Database>) -> Settings {    if let Some(store) = store {        match store.get_all_settings(DEFAULT_USER_ID).await {            Ok(map) if !map.is_empty() => return Settings::from_db_map(&map),            _ => {}        }    }    Settings::default()}/// List all settings.